<script module lang="ts">
/**
 * Several independent choices, all visible (`design/components/checkbox-group.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/checkbox-group.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import { Icon, agentMember, joinSlot, watchEffect } from '@polymorph/svelte'
import styles from '@polymorph/recipes/controls/checkbox-group.module.css'

export type CheckboxGroupOrientation = NonNullable<CheckboxGroupProps['orientation']>

export interface CheckboxGroupOption {
  value: string
  label: string
  description?: string
  disabled?: boolean
}

export interface CheckboxGroupProps {
  'aria-describedby'?: string
  /**
   * Set by FormField, because the group's question is the field's label.
   */
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-required'?: boolean
  defaultValue?: string[]
  disabled?: boolean
  id?: string
  invalid?: boolean
  /**
   * Set on every box, with each option's `value`, which is the native multi-value form data.
   */
  name?: string
  /**
   * Reports checked values in **options order**, not click order, so the result is stable and
   * comparable. The empty array is a lawful state, unlike Radio's no-null rule, because "none of
   * these" is a real answer to a multi-choice question.
   */
  onChange?: (values: string[]) => void
  /**
   * Items render from data, because free-form children invite custom layouts (Radio's law).
   */
  options: CheckboxGroupOption[]
  /**
   * Horizontal only for ≤3 short labels without descriptions (Radio's guidance, not enforced).
   */
  orientation?: 'horizontal' | 'vertical'
  value?: string[]
}

export const controlKind = 'group'
</script>

<script lang="ts">
let {
  'aria-describedby': ariaDescribedbyOwn,
  'aria-label': ariaLabel,
  'aria-labelledby': ariaLabelledbyOwn,
  'aria-required': ariaRequiredOwn,
  defaultValue,
  disabled = false,
  id: idOwn,
  invalid: invalidOwn = false,
  name,
  onChange,
  options,
  orientation = 'vertical',
  value,
}: CheckboxGroupProps = $props()
const uid = $props.id()
const joined = joinSlot(controlKind, () => ({ disabled: disabled, name: name }))
const ariaDescribedby = $derived(
  joined.passed['aria-describedby'] === undefined
    ? ariaDescribedbyOwn
    : (joined.passed['aria-describedby'] as typeof ariaDescribedbyOwn),
)
const ariaLabelledby = $derived(
  joined.passed['aria-labelledby'] === undefined
    ? ariaLabelledbyOwn
    : (joined.passed['aria-labelledby'] as typeof ariaLabelledbyOwn),
)
const ariaRequired = $derived(
  joined.passed['aria-required'] === undefined
    ? ariaRequiredOwn
    : (joined.passed['aria-required'] as typeof ariaRequiredOwn),
)
const id = $derived(
  joined.passed['id'] === undefined ? idOwn : (joined.passed['id'] as typeof idOwn),
)
const invalid = $derived(
  joined.passed['invalid'] === undefined
    ? invalidOwn
    : (joined.passed['invalid'] as typeof invalidOwn),
)
// svelte-ignore state_referenced_locally
let mirror = $state(defaultValue ?? [])
let group = $state<HTMLElement | null>(null)
const current = $derived(value ?? mirror)
const toggle = $derived((optionValue: string, checked: boolean) =>
  ((next: string[]) => ((mirror = next), onChange?.(next)))(
    options
      .filter((option) => (option.value === optionValue ? checked : current.includes(option.value)))
      .map((option) => option.value),
  ),
)
const choose = $derived((chosen: readonly string[]) =>
  ((next: string[]) =>
    next.length === current.length && next.every((each) => current.includes(each))
      ? undefined
      : ((mirror = next), onChange?.(next)))(
    options
      .filter((option) =>
        disabled || option.disabled === true
          ? current.includes(option.value)
          : chosen.includes(option.value),
      )
      .map((option) => option.value),
  ),
)
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'CheckboxGroup',
    element: () => group,
    state: () => ({
      value: current,
      options: options.map((option) => ({
        id: option.value,
        label: option.label,
        ...(option.disabled === true ? { disabled: true } : {}),
      })),
      disabled: disabled,
      invalid: invalid,
    }),
    actions: { choose: { argument: 'ids', run: (value) => choose(value) } },
  })
  release1 = () => {
    ran()
  }
}
watchEffect(effect1)
onDestroy(() => release1?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div
    bind:this={group}
    class={styles.group}
    {id}
    role="group"
    data-orientation={orientation}
    data-invalid={(invalid) ? '' : undefined}
    data-disabled={(disabled) ? '' : undefined}
    data-required={(ariaRequired) ? '' : undefined}
    aria-label={ariaLabel}
    aria-labelledby={ariaLabelledby}
    aria-describedby={ariaDescribedby}
    aria-invalid={(invalid) ? true : undefined}
    data-member="checkbox-group"
    >{#each options as option, index (option.value)
      }<div
        class={styles.item}
        data-disabled={(disabled || option.disabled === true) ? '' : undefined}
        ><label
          class={styles.row}
          data-state={(current.includes(option.value)) ? 'checked' : 'unchecked'}
          data-disabled={(disabled || option.disabled === true) ? '' : undefined}
          ><button
            class={styles.box}
            type="button"
            role="checkbox"
            value={option.value}
            aria-checked={current.includes(option.value)}
            disabled={disabled || option.disabled === true}
            aria-describedby={(option.description !== undefined) ? `${id ?? uid}-option-${index}-description` : undefined}
            data-state={(current.includes(option.value)) ? 'checked' : 'unchecked'}
            data-disabled={(disabled || option.disabled === true) ? '' : undefined}
            onclick={() => { toggle(option.value, !(current.includes(option.value))) }}
            onkeydown={(event) => { if (event.key === 'Enter') event.preventDefault() }}
            >{#if current.includes(option.value)
              }<span class={styles.indicator} data-state="checked"
                ><Icon name="confirm" size="sm"
              /></span
            >{/if
          }</button
          ><span class={styles.label}>{option.label}</span
        ></label
        >{#if option.description !== undefined
          }<span class={styles.description} id={`${id ?? uid}-option-${index}-description`}
            >{option.description
          }</span
        >{/if
        }{#if name !== undefined && current.includes(option.value)
          }<input type="hidden" {name} value={option.value}
        />{/if
      }</div
    >{/each
  }</div
>{/if
}{@render joined.end?.()}
